// План specs/audit-log.md, 4.2 (кейс AL-07, шаг 3). Супер-админ, бизнес test. Только просмотр. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage } from '../admin-plans/plans-helpers';
import { openAuditLogTab, auditRows, chooseAuditFilter } from './audit-helpers';

test.use({ storageState: '../auth/admin.json' });

test.describe('Admin Panel — Audit log (#fc4fa4)', () => {
  test('Super-admin expands a "Coupon changed" entry and sees Field / Before / After #fc4fa4 @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');
    await openAuditLogTab(page);
    await chooseAuditFilter(page, 'Coupons');

    const changed = auditRows(page).filter({ hasText: 'Coupon changed' }).first();
    await expect(changed, 'запись «Coupon changed»').toBeVisible({ timeout: 30_000 });
    await expect(page.getByText('Before', { exact: true })).toHaveCount(0);

    await changed.click();
    for (const h of ['Field', 'Before', 'After']) {
      await expect(page.getByText(h, { exact: true }).first(), `в деталях колонка «${h}»`).toBeVisible();
    }
  });
});
